# Numerical version of the FO2-joint algebra test (Lagrangian case dim T_1/X = 2(D - dim X)): dimension of the algebra generated by
# Q1^{-1} F (F in the span of the forms q_m on T_1/X). Full algebra (= nq^2) => no common invariant subspace => no common Lagrangian subspace.
import sys, numpy as np
A_=list(sys.argv); sys.argv=[A_[0]]
exec(open('/home/kevxhk/work/L-gct-210/stage2/r5_FO2.py').read().split("if __name__=='__main__':")[0])
rg=np.random.default_rng(7)
def analyse(f):
    Bf=np.load(f); X=np.zeros((len(Bf),5,5),complex); X[:,1:,:]=Bf; X=X.reshape(len(Bf),25)
    u,s,vh=np.linalg.svd(X,full_matrices=False); dX=int((s>1e-9*s[0]).sum()); X=vh[:dX]
    rows=[cof55(np.ones((5,5))+((rg.normal(size=dX)+1j*rg.normal(size=dX))@X).reshape(5,5)) for _ in range(80)]
    u,s,vh=np.linalg.svd(np.array(rows)); r=int((s>1e-8*s[0]).sum()); T=vh[r:].conj()
    Pj=T-(T@X.conj().T)@X; u,s,vh=np.linalg.svd(Pj); Q=vh[:len(T)-dX]; nq=len(Q)
    forms=[]
    for _ in range(60):
        m=(rg.normal(size=dX)+1j*rg.normal(size=dX))@X; H=hess(np.ones((5,5))+m.reshape(5,5)); forms.append(Q@H@Q.T)
    F=np.array(forms).reshape(len(forms),-1); sv=np.linalg.svd(F,compute_uv=False); N=int((sv>1e-9*sv[0]).sum())
    Fb=np.linalg.svd(F)[2][:N].reshape(N,nq,nq); Fb=[(g+g.T)/2 for g in Fb]
    Q1=sum((rg.normal()+1j*rg.normal())*g for g in Fb); cond=np.linalg.cond(Q1)
    Ms=[np.linalg.solve(Q1,g) for g in Fb]
    basis=[np.eye(nq).ravel()]; frontier=[np.eye(nq)]
    def rank(vs): s=np.linalg.svd(np.array(vs),compute_uv=False); return int((s>1e-8*s[0]).sum())
    cur=1
    for it in range(8):
        new=[]
        for W in frontier:
            for M in Ms:
                P=W@M; P=P/np.linalg.norm(P)
                if rank(basis+[P.ravel()])>cur: basis.append(P.ravel()); cur+=1; new.append(P)
        frontier=new
        if not new or cur==nq*nq: break
    print('%-26s dim X %d dim T_1 %d nq %d N %d cond(Q1) %.1e  algebra dim %d of %d %s'%(f.split('/')[-1],dX,len(T),nq,N,cond,cur,nq*nq,'FULL' if cur==nq*nq else ''),flush=True)
for f in A_[1:]: analyse(f)
